sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?song ?releaseDate WHERE {
  VALUES ?song { dbr:Sea_of_Voices dbr:Soft-Hearted_Hana }

  # Direct release date (prefer dbp:)
  OPTIONAL { ?song dbp:releaseDate ?releaseDate . }
  OPTIONAL { ?song dbo:releaseDate ?releaseDate . }

  # If not directly available, try to get the album's release date
  OPTIONAL {
    ?song dbo:album ?album .
    OPTIONAL { ?album dbp:releaseDate ?releaseDate . }
    OPTIONAL { ?album dbo:releaseDate ?releaseDate . }
  }
}
LIMIT 100

